/** The zone's wall clock at `ms`, expressed as if it were UTC. */
function wallMs(ms: number, timeZone: string): number {
  const parts: Record<string, number> = {};
  for (const p of zoneFormatter(timeZone).formatToParts(new Date(ms))) {
    if (p.type !== "literal") parts[p.type] = Number(p.value);
  }
  return Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour % 24,
    parts.minute,
    parts.second,
  );
}

function ymd(wall: number): string {
  return new Date(wall).toISOString().slice(0, 10);
}

/** The `YYYY-MM-DD` calendar date of an instant in the given zone. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return ymd(wallMs(parseIso(value).getTime(), timeZone));
}

function shiftDate(date: string, days: number): string {
  return ymd(Date.parse(`${date}T00:00:00Z`) + days * DAY_MS);
}

/** Instants (ascending) at which the zone's clock shows `date` `hour:00`. */
function localInstants(date: string, hour: number, timeZone: string): number[] {
  const target = Date.parse(`${date}T00:00:00Z`) + hour * HOUR_MS;
  const offsets = new Set<number>();
  for (const probe of [-DAY_MS, 0, DAY_MS]) {
    const t = target + probe;
    offsets.add(wallMs(t, timeZone) - Math.floor(t / 1000) * 1000);
  }
  const found = new Set<number>();
  for (const o of offsets) {
    const t = target - o;
    if (wallMs(t, timeZone) === target) found.add(t);
  }
  if (found.size === 0) {
    // The wall time falls in a spring-forward gap: use the first instant after it.
    const before = wallMs(target - DAY_MS, timeZone) - (target - DAY_MS);
    found.add(target - before);
  }
  return [...found].sort((a, b) => a - b);
}

/** The UTC instant at which the zone's calendar day containing `reference` began. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const date = ymd(wallMs(reference.getTime(), timeZone));
  return toIsoTimestamp(new Date(localInstants(date, 0, timeZone)[0]));
}

