  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return parseIso(dueAt).getTime() < parseIso(startOfLocalDay(reference, timeZone)).getTime();
}

