export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }
  const ref = reference.getTime();
  let date = ymd(wallMs(ref, timeZone));
  let end = localInstants(date, digestHour, timeZone).filter((t) => t <= ref).pop();
  if (end === undefined) {
    date = shiftDate(date, -1);
    end = localInstants(date, digestHour, timeZone).filter((t) => t <= ref).pop()!;
  }
  const start = localInstants(shiftDate(date, -1), digestHour, timeZone)[0];
  return { start: toIsoTimestamp(new Date(start)), end: toIsoTimestamp(new Date(end)) };
}
